<?php
declare(strict_types=1);
require_once __DIR__.'/WorkspaceUI.php';
require_once __DIR__.'/Database.php';
require_once __DIR__.'/Auth.php';
require_once __DIR__.'/AppNavigation.php';
require_once __DIR__.'/AccessPolicy.php';
require_once __DIR__.'/ProductionContext.php';
require_once __DIR__.'/ProductionRosterService.php';
require_once __DIR__.'/ManualParticipantService.php';

final class ProductionPeopleExperience
{
    public static function handles(string $route):bool{return $route==='/production/people';}
    public static function render(string $route,string $basePath):never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$user=Auth::currentUser($db);
        if(!$user)self::redirect($basePath.'/login');
        if(!AccessPolicy::canManageProduction($user)){http_response_code(403);exit('Production management permission required.');}
        $production=ProductionContext::selected($db,$user);
        if($production&&!in_array('administrator',Auth::roles($db,(int)$user['id']),true)&&ProductionContext::audienceType($db,(int)$user['id'],(int)$production['id'])!=='staff'){http_response_code(403);exit('Current production staff access required.');}
        $_SESSION['production_people_csrf']??=bin2hex(random_bytes(24));
        if($_SERVER['REQUEST_METHOD']==='POST'){
            try{
                if(!hash_equals($_SESSION['production_people_csrf'],(string)($_POST['csrf_token']??'')))throw new RuntimeException('Your session token expired. Reload People and try again.');
                if(!$production||(int)($_POST['production_id']??0)!==(int)$production['id'])throw new RuntimeException('The working production changed. Reload People before saving.');
                $action=(string)($_POST['action']??'');
                if($action==='save_team')ProductionParticipantFunctionService::saveAssignment($db,(int)$production['id'],(int)$user['id'],$_POST);
                elseif($action==='remove_team')ProductionParticipantFunctionService::remove($db,(int)$production['id'],(int)$user['id'],(int)($_POST['assignment_id']??0),(int)($_POST['revision']??0));
                else throw new RuntimeException('Casting, Family & Pickup and Account & Access own other roster changes. Choose a Production Team action here.');
                $_SESSION['production_people_flash']=['type'=>'success','message'=>$action==='remove_team'?'Team assignment removed. Independent cast, family and staff responsibilities are retained.':'Production Team assignment saved. Account permissions are unchanged.'];
            }catch(RuntimeException $e){$_SESSION['production_people_flash']=['type'=>'error','message'=>$e->getMessage()];if(($_POST['action']??'')==='save_team')$_SESSION['production_team_input']=$_POST;}
            self::redirect($basePath.'/production/people');
        }
        self::page($db,$basePath,$user,$production);
    }
    private static function page(PDO $db,string $base,array $viewer,?array $production):never
    {
        $e=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$url=static fn(string $p):string=>$base.$p;
        $flash=$_SESSION['production_people_flash']??null;unset($_SESSION['production_people_flash']);$retry=$_SESSION['production_team_input']??null;unset($_SESSION['production_team_input']);
        $people=$production?ProductionRosterService::people($db,(int)$production['id']):[];$counts=ProductionRosterService::counts($people);
        $filter=(string)($_GET['view']??'all');$filters=['all'=>'All People','cast'=>'Cast','team'=>'Production Team','guardians'=>'Guardians','staff'=>'Staff'];if(!isset($filters[$filter]))$filter='all';
        $search=trim((string)($_GET['q']??''));$visible=array_filter($people,static fn(array $p):bool=>($filter==='all'||isset($p['filters'][$filter]))&&($search===''||mb_stripos($p['name'].' '.implode(' ',$p['involvement']).' '.implode(' ',$p['roles']),$search)!==false));
        $closed=$production&&in_array($production['lifecycle_stage'],['completed','archived'],true);$canAccounts=AccessPolicy::canManageAccounts($viewer);
        $assignments=$production?ProductionParticipantFunctionService::assignments($db,(int)$production['id'],true):[];$candidates=$production&&!$closed?ProductionParticipantFunctionService::candidates($db):[];
        $editing=null;foreach($assignments as $a)if((int)$a['id']===(int)($_GET['edit_team']??0))$editing=$a;
        $openEditor=isset($_GET['add_team'])||$editing||$retry;
        $input=array_replace(['user_id'=>0,'function_type'=>'creative','function_code'=>'director','title'=>'','display_order'=>0,'staff_notes'=>'','playbill_eligible'=>0],$editing?:[],$retry?:[]);
        $manual=$production?ManualParticipantService::forProduction($db,(int)$production['id']):[];
        header('Content-Type:text/html; charset=utf-8');
        ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Production People · CTSMD Connect</title><link rel="stylesheet" href="<?=$url('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/unified-navigation.css')?>"><?php WorkspaceUI::operationsStyles($base);?><link rel="stylesheet" href="<?=$url('/assets/css/production-people.css?v=20261029-team')?>"></head><body class="app-body ux-operations ux-workspace"><a class="ux-skip" href="#people-main">Skip to main content</a><div class="unified-shell"><?php AppNavigation::renderSidebar('/production/people',$base,$viewer);?><main class="unified-main" id="people-main" tabindex="-1"><?php AppNavigation::renderHeader('Production','People',$base,AppNavigation::productionSubnav('/production/people',$viewer));?><div class="people-page ops-page">
        <?php if($flash):?><div class="people-flash <?=$e($flash['type'])?>" role="<?=$flash['type']==='error'?'alert':'status'?>"><?=$e($flash['message'])?></div><?php endif;?>
        <header class="people-heading ops-heading"><div><h1>Production People</h1><p><?=$production?$e($production['title']).' · One person, all their responsibilities.':'Select a production to see its people.'?></p></div><?php if($production&&!$closed):?><a class="button" href="<?=$url('/production/people?add_team=1#team-editor')?>">Add Production Team Member</a><?php endif;?></header>
        <?php if(!$production):?><section class="people-empty ops-panel"><h2>No production selected</h2><p>Choose a working production to review cast, team and family involvement.</p><a href="<?=$url('/production')?>">Choose production</a></section><?php else:?>
        <?php if($closed):?><p class="people-notice" role="status">This production is <?=$e($production['lifecycle_stage'])?>. Responsibilities and retained credits are read-only.</p><?php endif;?>
        <nav class="people-workflows" aria-label="Manage production responsibilities"><a href="<?=$url('/production/casting')?>">Manage Casting</a><a href="<?=$url('/production/people?view=team')?>">Manage Production Team</a><a href="<?=$url('/production/people?families=1#family-directory')?>">Manage Family &amp; Pickup</a><a href="<?=$url('/admin/volunteer-shifts')?>">Volunteer Management</a></nav>
        <section class="people-directory ops-panel" aria-labelledby="directory-title"><div class="people-directory-head"><h2 id="directory-title"><?=$counts['all']?> unique people</h2><p><?=$counts['team']?> team members · <?=$counts['assignments']?> team assignments. Filter totals overlap.</p></div>
        <nav class="people-filters" aria-label="People filters"><?php foreach($filters as $key=>$label):?><a href="<?=$url('/production/people?'.http_build_query(['view'=>$key,'q'=>$search]))?>" <?=$filter===$key?'aria-current="page"':''?>><?=$label?> <span><?=$counts[$key]?></span></a><?php endforeach;?></nav>
        <form method="get" class="people-search ops-form"><input type="hidden" name="view" value="<?=$e($filter)?>"><label for="people-search">Search people, responsibilities or roles</label><div><input id="people-search" name="q" type="search" maxlength="190" value="<?=$e($search)?>"><button type="submit">Search</button></div></form>
        <?php if(!$visible):?><div class="people-empty"><h3><?=$search?'No matching people':'No people in this view yet'?></h3><p><?=$search?'Try another name or clear your search.':'Cast acceptance, family relationships and team assignments appear here automatically.'?></p></div><?php else:?><div class="people-table-wrap"><table class="people-table"><caption class="sr-only"><?=$e($filters[$filter])?> — <?=count($visible)?> unique people shown</caption><thead><tr><th scope="col">Person</th><th scope="col">Production involvement</th><th scope="col">Account authorization</th><th scope="col">Actions</th></tr></thead><tbody>
        <?php foreach($visible as $person):?><tr data-person-id="<?=$person['id']?>"><th scope="row"><span class="people-name"><?=$e($person['name'])?></span></th><td data-label="Production involvement"><ul class="people-responsibilities"><?php foreach($person['involvement'] as $responsibility):?><li><?=$e($responsibility)?></li><?php endforeach;?></ul></td><td data-label="Account authorization"><?= $e(implode(', ',$person['roles'])?:'No authorization roles')?></td><td data-label="Actions"><a href="<?=$url('/production/people?'.http_build_query(['view'=>$filter,'q'=>$search,'person'=>$person['id']]).'#person-'.$person['id'])?>">View responsibilities<span class="sr-only"> for <?=$e($person['name'])?></span></a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
        <?php if($manual):?><p class="people-footnote"><?=count($manual)?> manual casting credits are managed in <a href="<?=$url('/production/casting')?>">Casting</a>. They are not additional account identities.</p><?php endif;?>
        <details class="people-history ops-panel"><summary>Retained team assignment history</summary><p>Removed functions and unavailable accounts remain in audit and Theatre History.</p><ul><?php foreach($assignments as $a):?><li><?=$e($a['name'])?> · <?=$e($a['title'])?> — <?=$e($a['status'])?><?=$a['account_status']==='disabled'?' · account disabled':''?></li><?php endforeach;?></ul></details>
        <dialog class="people-drawer" id="family-directory" aria-labelledby="family-directory-title" <?=isset($_GET['families'])?'open data-auto-modal':''?>><header><h2 id="family-directory-title">Manage Family &amp; Pickup</h2><a href="<?=$url('/production/people')?>" data-people-close aria-label="Close family directory">Close</a></header><div class="people-drawer-body"><p>Choose a participating Student. Relationships and pickup authority are managed on their existing Family &amp; Pickup page.</p><ul><?php foreach($people as $student):if(!$student['is_student'])continue;?><li><a href="<?=$url('/student-profile/family?student='.$student['id'])?>"><?=$e($student['name'])?></a></li><?php endforeach;?></ul></div></dialog>
        <?php foreach($people as $person):$open=(int)($_GET['person']??0)===$person['id'];?><dialog class="people-drawer" id="person-<?=$person['id']?>" aria-labelledby="person-title-<?=$person['id']?>" <?=$open?'open data-auto-modal':''?>><header><h2 id="person-title-<?=$person['id']?>"><?=$e($person['name'])?></h2><a href="<?=$url('/production/people?view='.$filter)?>" data-people-close aria-label="Close responsibilities">Close</a></header><div class="people-drawer-body"><h3>Production involvement</h3><ul><?php foreach($person['involvement'] as $r):?><li><?=$e($r)?></li><?php endforeach;?></ul>
        <?php if(isset($person['filters']['cast'])):?><p><a href="<?=$url('/production/casting')?>">Manage or remove cast assignment in Casting</a></p><?php endif;?>
        <?php if($person['is_student']):?><p><a href="<?=$url('/student-profile/family?student='.$person['id'])?>">Manage this Student’s Family &amp; Pickup</a></p><?php endif;?>
        <?php foreach($person['children'] as $childId=>$childName):?><p><a href="<?=$url('/student-profile/family?student='.$childId)?>">Manage Family &amp; Pickup for <?=$e($childName)?></a></p><?php endforeach;?>
        <?php foreach($person['team'] as $team):?><section class="people-assignment"><h3><?=$e($team['title'])?></h3><p><?=$e(ProductionParticipantFunctionService::CATEGORIES[$team['function_type']])?> · order <?=(int)$team['display_order']?> · <?=$team['playbill_eligible']?'Eligible for Playbill review':'Not marked for Playbill'?></p><?php if($team['staff_notes']):?><h4>Private staff notes</h4><p class="people-notes"><?=$e($team['staff_notes'])?></p><?php endif;?><?php if(!$closed):?><a href="<?=$url('/production/people?edit_team='.$team['id'].'#team-editor')?>">Edit team assignment</a><form method="post" class="people-remove"><input type="hidden" name="csrf_token" value="<?=$e($_SESSION['production_people_csrf'])?>"><input type="hidden" name="production_id" value="<?=(int)$production['id']?>"><input type="hidden" name="assignment_id" value="<?=(int)$team['id']?>"><input type="hidden" name="revision" value="<?=(int)$team['revision']?>"><button type="submit" name="action" value="remove_team">Remove Team Assignment<span class="sr-only">: <?=$e($team['title'])?></span></button></form><?php endif;?></section><?php endforeach;?>
        <h3>Account authorization</h3><p><?=$e(implode(', ',$person['roles'])?:'No authorization roles')?></p><details><summary>Current permission codes</summary><ul><?php foreach($person['permissions'] as $permission):?><li><?=$e($permission)?></li><?php endforeach;?></ul></details><p>Team credits do not grant permissions, guardian access or pickup authority.</p><?php if($canAccounts):?><a href="<?=$url('/admin/accounts/view?id='.$person['id'])?>">Manage account authorization &amp; staff access</a><?php endif;?></div></dialog><?php endforeach;?>
        <?php if(!$closed):?><dialog class="people-drawer" id="team-editor" aria-labelledby="team-editor-title" <?=$openEditor?'open data-auto-modal':''?>><header><h2 id="team-editor-title"><?=$editing?'Edit team assignment':'Add Production Team Member'?></h2><a href="<?=$url('/production/people?view=team')?>" data-people-close aria-label="Close team editor">Close</a></header><div class="people-drawer-body"><p>Assign a responsibility to an existing account. Account permissions and family relationships stay separate.</p><form method="post" class="people-team-form ops-form"><input type="hidden" name="csrf_token" value="<?=$e($_SESSION['production_people_csrf'])?>"><input type="hidden" name="production_id" value="<?=(int)$production['id']?>"><input type="hidden" name="assignment_id" value="<?=(int)($retry['assignment_id']??$editing['id']??0)?>"><input type="hidden" name="revision" value="<?=(int)($input['revision']??0)?>">
        <label>Person<select name="user_id" required <?=$editing?'aria-describedby="team-person-help"':''?>><option value="">Choose an existing account</option><?php foreach($candidates as $c):if($editing&&(int)$c['id']!==(int)$editing['user_id'])continue;?><option value="<?=(int)$c['id']?>" <?=(int)$c['id']===(int)$input['user_id']?'selected':''?>><?=$e($c['name'].' · '.$c['roles'])?></option><?php endforeach;?></select></label><p id="team-person-help">Current authorization roles are shown for context. Change access in Account &amp; Access.</p>
        <label>Team category<select name="function_type" id="team-category"><?php foreach(ProductionParticipantFunctionService::CATEGORIES as $key=>$label):?><option value="<?=$key?>" <?=$input['function_type']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label>
        <label>Function<select name="function_code" id="team-function"><?php foreach(ProductionParticipantFunctionService::LABELS as $category=>$labels):?><optgroup label="<?=$e(ProductionParticipantFunctionService::CATEGORIES[$category])?>" data-category="<?=$category?>"><?php foreach($labels as $code=>$label):?><option value="<?=$code?>" data-category="<?=$category?>" <?=$input['function_type']===$category&&$input['function_code']===$code?'selected':''?>><?=$e($label)?></option><?php endforeach;?></optgroup><?php endforeach;?></select></label>
        <label id="team-custom">Custom title (for a custom function)<input name="custom_title" maxlength="190" value="<?=$e($input['custom_title']??($input['function_code']==='custom'?$input['title']:''))?>"></label><label>Display order (optional)<input name="display_order" type="number" min="-10000" max="10000" value="<?=$e($input['display_order'])?>"></label><label>Private staff notes (optional)<textarea name="staff_notes" rows="4" maxlength="2000"><?=$e($input['staff_notes'])?></textarea></label><label class="people-checkbox"><input type="checkbox" name="playbill_eligible" value="1" <?=$input['playbill_eligible']?'checked':''?>>Credit eligible for Playbill review</label><p>Eligibility never publishes a name, biography, photo or contact information automatically. Publication approval stays in Playbill.</p><button type="submit" name="action" value="save_team">Save team assignment</button></form></div></dialog><?php endif;?>
        <?php endif;?></div></main></div><script src="<?=$url('/assets/js/unified-navigation.js')?>"></script><script src="<?=$url('/assets/js/production-people.js')?>" defer></script></body></html><?php exit;
    }
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
}
